export const main="<section id=\"sw-welcome\" aria-labelledby=\"sw-title\">\n  <div class=\"sw-hero\">\n    <img class=\"sw-hero-photo\" src=\"/start-here/assets/hero.webp\" alt=\"A bald, bearded man taking a moment after exercise\" width=\"1536\" height=\"1024\" fetchpriority=\"high\">\n    <div class=\"sw-hero-shade\"></div>\n    <div class=\"sw-wrap sw-hero-copy\">\n      <h1 id=\"sw-title\">Your next step<br><span>starts here.</span></h1>\n      <p>Choose what you want help with. Free everyday support, weight-loss guidance and clearer routes to better health.</p>\n      <a class=\"sw-button sw-outline\" href=\"#sw-routes\">Explore your routes <svg aria-hidden=\"true\" viewBox=\"0 0 24 24\"><path d=\"M12 4v16m-6-6 6 6 6-6\"/></svg></a>\n    </div>\n  </div>\n  <div class=\"sw-wrap sw-routes\">\n    <section class=\"sw-feature sw-free\" aria-labelledby=\"sw-free-title\">\n      <img src=\"/start-here/assets/support.webp\" alt=\"A notebook with small everyday priorities beside a green water bottle\" width=\"1536\" height=\"1024\">\n      <div class=\"sw-feature-shade\"></div>\n      <div class=\"sw-feature-copy\">\n        <h2 id=\"sw-free-title\">Start with <span>free support</span></h2>\n        <p>Free My Timber tools for food, movement, check-ins and progress. Start with one useful change, at your own pace.</p>\n        <a class=\"sw-button sw-green\" href=\"/join-my-timber\">Join My Timber free</a>\n      </div>\n    </section>\n    <section class=\"sw-feature sw-weight\" id=\"sw-routes\" aria-labelledby=\"sw-weight-title\">\n      <img src=\"/start-here/assets/weight.webp\" alt=\"A man preparing vegetables in his kitchen\" width=\"1536\" height=\"1024\" loading=\"lazy\">\n      <div class=\"sw-feature-shade\"></div>\n      <div class=\"sw-feature-copy\">\n        <p class=\"sw-eyebrow\">Weight management</p>\n        <h2 id=\"sw-weight-title\">Find your way<br>to <span>weight loss.</span></h2>\n        <p>A few useful questions help you explore practical support and treatment routes.</p>\n        <a class=\"sw-button sw-cream\" href=\"/start-here?route=weight-loss#weight-loss-questions\" data-weight-start>Find my weight-loss route <svg aria-hidden=\"true\" viewBox=\"0 0 24 24\"><path d=\"M4 12h16m-6-6 6 6-6 6\"/></svg></a>\n        <a class=\"sw-switch\" href=\"/provider-switch\">Already on treatment? Read our switching guide <svg aria-hidden=\"true\" viewBox=\"0 0 24 24\"><path d=\"M4 12h16m-6-6 6 6-6 6\"/></svg></a>\n      </div>\n    </section>\n    <h2 class=\"sw-other-title\">Other routes <span>to explore</span></h2>\n    <div class=\"sw-other-grid\">\n      <article class=\"sw-route-card\">\n        <img src=\"/start-here/assets/health.webp\" alt=\"A man looking thoughtfully out of a window\" width=\"1024\" height=\"1536\" loading=\"lazy\">\n        <div><h3>Understand<br>your health</h3><p>Explore energy, sleep, heart health and more.</p><a class=\"sw-button sw-green\" href=\"/shift-health\">Explore SHIFT Health</a></div>\n      </article>\n      <article class=\"sw-route-card\">\n        <img src=\"/start-here/assets/blood.webp\" alt=\"A gloved hand holding a closed blood sample tube\" width=\"1024\" height=\"1536\" loading=\"lazy\">\n        <div><h3>Understand<br>blood tests</h3><p>Learn what testing can and cannot tell you.</p><a class=\"sw-button sw-green\" href=\"/shift-health/blood-tests\">Explore blood tests</a></div>\n      </article>\n    </div>\n    <p class=\"sw-boundary\"><svg aria-hidden=\"true\" viewBox=\"0 0 24 24\"><circle cx=\"12\" cy=\"12\" r=\"9\"/><path d=\"M12 11v6m0-10v1\"/></svg> Any treatment decision requires an appropriate clinical assessment.</p>\n  </div>\n</section>\n<section id=\"sw-questions\" class=\"sw-wrap\" aria-labelledby=\"sw-question-title\" hidden>\n  <a class=\"sw-text-link\" href=\"/start-here\" data-welcome-back><svg aria-hidden=\"true\" viewBox=\"0 0 24 24\"><path d=\"M20 12H4m6-6-6 6 6 6\"/></svg> All starting points</a>\n  <p class=\"sw-eyebrow\">Your weight-loss starting point</p>\n  <h1 id=\"sw-question-title\">A few choices.<br><span>A clearer next step.</span></h1>\n  <p class=\"sw-intro\">Tell us what matters to you. These questions help you explore support; they do not decide which medicine is suitable.</p>\n  <div class=\"sw-question-box\" id=\"weight-loss-questions\">\n    <div class=\"sw-progress\"><p data-quick-count>Question 1 of 3</p><div role=\"progressbar\" aria-label=\"Question progress\" aria-valuemin=\"1\" aria-valuemax=\"3\" aria-valuenow=\"1\"><i data-quick-bar></i></div></div>\n    <section data-quick-step=\"0\">\n      <h2 tabindex=\"-1\">What would you like to change?</h2><p class=\"sw-question-hint\">You’re exploring weight-loss support. Choose anything else that matters to you.</p>\n      <div class=\"sw-choices\" data-multi=\"why\">\n        <button type=\"button\" data-choice=\"Lose weight\" aria-pressed=\"true\" aria-disabled=\"true\"><strong>Lose weight</strong><small>The route you’ve chosen</small><span class=\"sw-choice-mark\" aria-hidden=\"true\"></span></button>\n        <button type=\"button\" data-choice=\"Feel more energy\" aria-pressed=\"false\"><strong>Feel more energy</strong><small>Make more of everyday life</small><span class=\"sw-choice-mark\" aria-hidden=\"true\"></span></button>\n        <button type=\"button\" data-choice=\"Health worries\" aria-pressed=\"false\"><strong>Health worries</strong><small>Understand my wider health</small><span class=\"sw-choice-mark\" aria-hidden=\"true\"></span></button>\n        <button type=\"button\" data-choice=\"Confidence\" aria-pressed=\"false\"><strong>Confidence</strong><small>Feel more comfortable in myself</small><span class=\"sw-choice-mark\" aria-hidden=\"true\"></span></button>\n        <button type=\"button\" data-choice=\"Feel like myself again\" aria-pressed=\"false\"><strong>Feel like myself again</strong><small>Find a routine I can keep using</small><span class=\"sw-choice-mark\" aria-hidden=\"true\"></span></button>\n      </div>\n    </section>\n    <section data-quick-step=\"1\" hidden>\n      <h2 tabindex=\"-1\">What are you open to?</h2><p class=\"sw-question-hint\">A preference helps you explore. It doesn’t commit you to treatment.</p>\n      <div class=\"sw-choices sw-two\" data-one=\"med\">\n        <button type=\"button\" data-choice=\"Jabs\" aria-pressed=\"false\"><strong>Jabs</strong><small>I’m open to injections</small><span class=\"sw-choice-mark\" aria-hidden=\"true\"></span></button>\n        <button type=\"button\" data-choice=\"Tablets\" aria-pressed=\"false\"><strong>Tablets</strong><small>I’d prefer an oral option</small><span class=\"sw-choice-mark\" aria-hidden=\"true\"></span></button>\n        <button type=\"button\" data-choice=\"Either\" aria-pressed=\"false\"><strong>Either</strong><small>I’d like to understand both</small><span class=\"sw-choice-mark\" aria-hidden=\"true\"></span></button>\n        <button type=\"button\" data-choice=\"No medication\" aria-pressed=\"false\"><strong>No medication</strong><small>Show me practical support</small><span class=\"sw-choice-mark\" aria-hidden=\"true\"></span></button>\n      </div>\n      <h3 class=\"sw-access-title\">Which access route would you like to explore?</h3>\n      <div class=\"sw-choices sw-three\" data-one=\"access\"><button type=\"button\" data-choice=\"NHS\" aria-pressed=\"false\"><strong>NHS</strong><span class=\"sw-choice-mark\" aria-hidden=\"true\"></span></button><button type=\"button\" data-choice=\"Private\" aria-pressed=\"false\"><strong>Private</strong><span class=\"sw-choice-mark\" aria-hidden=\"true\"></span></button><button type=\"button\" data-choice=\"Both\" aria-pressed=\"false\"><strong>Both</strong><span class=\"sw-choice-mark\" aria-hidden=\"true\"></span></button></div>\n    </section>\n    <section data-quick-step=\"2\" hidden>\n      <h2 tabindex=\"-1\">Could weight-loss treatment be right for you?</h2><p class=\"sw-question-hint\">For adults aged 18 and over. This quick check helps explain your options; a prescriber confirms suitability.</p>\n<h3>Are you starting or already on treatment?</h3><div class=\"sw-choices sw-two\" data-one=\"stage\"><button type=\"button\" data-choice=\"new\" aria-pressed=\"false\"><strong>Starting treatment</strong><span class=\"sw-choice-mark\" aria-hidden=\"true\"></span></button><button type=\"button\" data-choice=\"continuing\" aria-pressed=\"false\"><strong>Already prescribed treatment / switching</strong><span class=\"sw-choice-mark\" aria-hidden=\"true\"></span></button></div><h3>What is your current BMI?</h3><div class=\"sw-choices sw-two\" data-one=\"bmi\"><button type=\"button\" data-choice=\"30\" aria-pressed=\"false\"><strong>30 or above</strong><span class=\"sw-choice-mark\" aria-hidden=\"true\"></span></button><button type=\"button\" data-choice=\"28\" aria-pressed=\"false\"><strong>28 to below 30</strong><span class=\"sw-choice-mark\" aria-hidden=\"true\"></span></button><button type=\"button\" data-choice=\"27\" aria-pressed=\"false\"><strong>27 to below 28</strong><span class=\"sw-choice-mark\" aria-hidden=\"true\"></span></button><button type=\"button\" data-choice=\"below\" aria-pressed=\"false\"><strong>Below 27</strong><span class=\"sw-choice-mark\" aria-hidden=\"true\"></span></button><button type=\"button\" data-choice=\"unknown\" aria-pressed=\"false\"><strong>I’m not sure</strong><span class=\"sw-choice-mark\" aria-hidden=\"true\"></span></button></div><details class=\"sw-inline-details\"><summary>Help me calculate my BMI</summary><div><label>Height in centimetres <input id=\"sw-height\" type=\"number\" min=\"120\" max=\"230\" step=\"0.1\" inputmode=\"decimal\"></label><label>Weight in kilograms <input id=\"sw-weight-kg\" type=\"number\" min=\"35\" max=\"320\" step=\"0.1\" inputmode=\"decimal\"></label><button type=\"button\" id=\"sw-calculate\" class=\"sw-button sw-outline\">Calculate BMI</button><p id=\"sw-bmi-calculated\" role=\"status\"></p></div></details>\n<div id=\"sw-condition\" hidden><h3>Have you been diagnosed with a weight-related health condition?</h3><p>For example, high blood pressure, type 2 diabetes or sleep apnoea. The prescriber checks whether your condition qualifies for the treatment.</p><div class=\"sw-choices sw-two\" data-one=\"condition\"><button type=\"button\" data-choice=\"yes\" aria-pressed=\"false\"><strong>Yes</strong><span class=\"sw-choice-mark\" aria-hidden=\"true\"></span></button><button type=\"button\" data-choice=\"no\" aria-pressed=\"false\"><strong>No</strong><span class=\"sw-choice-mark\" aria-hidden=\"true\"></span></button><button type=\"button\" data-choice=\"unknown\" aria-pressed=\"false\"><strong>I’m not sure</strong><span class=\"sw-choice-mark\" aria-hidden=\"true\"></span></button></div></div>\n    </section>\n    <p class=\"sw-validation\" data-quick-validation role=\"status\" aria-live=\"polite\"></p>\n    <div class=\"sw-controls\"><button type=\"button\" class=\"sw-text-link\" data-quick-back hidden>Back</button><button type=\"button\" class=\"sw-button sw-cream\" data-quick-next>Continue <svg aria-hidden=\"true\" viewBox=\"0 0 24 24\"><path d=\"M4 12h16m-6-6 6 6-6 6\"/></svg></button></div>\n  </div>\n</section>\n<section id=\"sw-result\" class=\"sw-wrap\" hidden aria-labelledby=\"sw-result-title\">\n  <p class=\"sw-eyebrow\">Based on the choices you made</p><h1 id=\"sw-result-title\" tabindex=\"-1\">Your weight-loss<br><span>starting point.</span></h1>\n  <p class=\"sw-intro\" id=\"sw-result-reason\"></p><dl class=\"sw-summary\" id=\"sw-summary\"></dl><button type=\"button\" class=\"sw-text-link\" id=\"sw-edit\">Edit my answers <svg aria-hidden=\"true\" viewBox=\"0 0 24 24\"><path d=\"M4 12h16m-6-6 6 6-6 6\"/></svg></button>\n  <section class=\"sw-result-route\" aria-labelledby=\"sw-route-title\"><p class=\"sw-eyebrow\">Why explore this route?</p><h2 id=\"sw-route-title\"></h2><p id=\"sw-route-reason\"></p><p id=\"sw-route-budget\"></p><a class=\"sw-button sw-cream\" id=\"sw-route-link\"></a></section>\n  <section id=\"sw-medicines\" aria-labelledby=\"sw-medicines-title\" hidden><h2 id=\"sw-medicines-title\">Your treatment options</h2><p id=\"sw-match-explanation\" role=\"status\"></p><div id=\"sw-medicine-grid\" class=\"sw-medicine-grid\"></div><button id=\"sw-retry-catalogue\" class=\"sw-button sw-outline\" type=\"button\" hidden>Retry live prices</button></section>\n  <div class=\"sw-result-free\"><p class=\"sw-eyebrow\">Free, whichever route you take</p><h2>Start with free My Timber.</h2><p id=\"sw-support-reason\"></p><a class=\"sw-button sw-green\" href=\"/join-my-timber\">Join My Timber free</a></div>\n  <section class=\"sw-result-health\" hidden><h2>Keep your wider health in view.</h2><p id=\"sw-health-reason\"></p><a class=\"sw-text-link\" href=\"/shift-health\">Explore SHIFT Health <svg aria-hidden=\"true\" viewBox=\"0 0 24 24\"><path d=\"M4 12h16m-6-6 6 6-6 6\"/></svg></a></section>\n  <details class=\"sw-inline-details sw-switch-details\"><summary>Already on treatment or changing provider?</summary><div><p>You can compare another option without starting your story again. On the treatment page, choose continuing treatment and give your current medicine and dose for review.</p><ul><li>Have your current medicine, strength and last dose date ready.</li><li>Bring a prescription, dispensing label or previous order record, plus any side effects or treatment gaps.</li><li>The new prescriber decides whether the current dose can continue. Changing medicine or restarting after a gap needs a clinical plan.</li></ul><p>Compare the same strength, pack quantity and supply period. A starter price is not the ongoing cost. Your existing My Timber account and practical support stay with you.</p></div></details>\n  <p class=\"sw-boundary\">These are routes to information and support. Clinical suitability, medicine and dose require an appropriate assessment by a prescribing service.</p><a class=\"sw-text-link\" href=\"/start-here\" data-welcome-back>Explore all starting points</a>\n</section>\n<noscript><p class=\"sw-noscript\">You can explore My Timber, SHIFT Health and blood tests using the links above. For weight-loss support, <a href=\"/treatment-centre\">explore treatment information</a> or <a href=\"/guides/nhs-weight-management-uk-guide\">read about NHS routes</a>.</p></noscript>\n";
